//! The shared value semantics of Mold: display, escaping, truthiness, comparison, arithmetic and filters.
//!
//! The runtime interpreter applies these to [`Value`]; code generated by `#[derive(Mold)]` applies the same
//! functions to Rust values through the traits here. Both modes produce byte-identical output because both go
//! through this module.

use crate::Value;
use crate::ast::BinOp;
use crate::value::f32_to_f64;
use serde::Serialize;
use std::borrow::Cow;
use std::collections::{BTreeMap, HashMap};
use std::fmt::Write as _;
use std::hash::BuildHasher;
use std::rc::Rc;
use std::sync::Arc;

/// HTML-escapes `s` (`& < > " '`) onto `out`.
pub fn escape_into(out: &mut String, s: &str) {
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            '\'' => out.push_str("&#39;"),
            c => out.push(c),
        }
    }
}

/// HTML-escapes `s`.
pub fn escape(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    escape_into(&mut out, s);
    out
}

/// Already-safe HTML, written without escaping: what a component slot renders to.
///
/// Internal to Mold (generated code builds slots with it). It renders raw in both modes: [`crate::to_value`] turns
/// it into [`Value::Safe`] for the interpreter, the same as the slot values the interpreter builds itself.
#[doc(hidden)]
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct Safe(pub String);

/// The newtype-struct name `Safe` serializes under, so [`crate::to_value`] can tell it from a plain string.
pub(crate) const SAFE_NAME: &str = "__mold_safe";

impl Serialize for Safe {
    fn serialize<S: serde::Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        // Any other serializer (JSON included) sees the plain string.
        s.serialize_newtype_struct(SAFE_NAME, &self.0)
    }
}

/// The template `null` literal: displays as nothing, is falsy.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Serialize)]
pub struct Null;

/// The `loop` variable inside `@for`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
#[non_exhaustive]
pub struct Loop {
    /// 1-based position.
    pub index: usize,
    /// 0-based position.
    pub index0: usize,
    /// The first iteration.
    pub first: bool,
    /// The last iteration.
    pub last: bool,
    /// The number of items.
    pub count: usize,
}

impl Loop {
    /// The loop state for item `index0` of `count`.
    pub fn new(index0: usize, count: usize) -> Self {
        Self {
            index: index0 + 1,
            index0,
            first: index0 == 0,
            last: index0 + 1 == count,
            count,
        }
    }

    /// The same state as a map [`Value`], for the interpreter.
    pub fn to_value(&self) -> Value {
        let int = |n: usize| Value::Int(i64::try_from(n).unwrap_or(i64::MAX));
        Value::Map(vec![
            ("index".into(), int(self.index)),
            ("index0".into(), int(self.index0)),
            ("first".into(), Value::Bool(self.first)),
            ("last".into(), Value::Bool(self.last)),
            ("count".into(), int(self.count)),
        ])
    }
}

/// A scalar view of a value, used for comparisons, arithmetic and `default`.
#[derive(Debug, Clone, PartialEq, Serialize)]
#[serde(untagged)]
#[non_exhaustive]
pub enum Scalar<'a> {
    /// Nothing (`None`, `null`).
    Null,
    /// A boolean.
    Bool(bool),
    /// An integer that fits in `i64`.
    Int(i64),
    /// An integer above `i64::MAX`.
    UInt(u64),
    /// A float.
    Float(f64),
    /// A string.
    Str(Cow<'a, str>),
}

impl Scalar<'_> {
    /// Detaches the scalar from what it borrows.
    pub fn into_owned(self) -> Scalar<'static> {
        match self {
            Scalar::Null => Scalar::Null,
            Scalar::Bool(b) => Scalar::Bool(b),
            Scalar::Int(i) => Scalar::Int(i),
            Scalar::UInt(u) => Scalar::UInt(u),
            Scalar::Float(f) => Scalar::Float(f),
            Scalar::Str(s) => Scalar::Str(Cow::Owned(s.into_owned())),
        }
    }

    fn kind(&self) -> &'static str {
        match self {
            Scalar::Null => "null",
            Scalar::Bool(_) => "a boolean",
            Scalar::Int(_) | Scalar::UInt(_) => "an integer",
            Scalar::Float(_) => "a float",
            Scalar::Str(_) => "a string",
        }
    }

    fn as_i128(&self) -> Option<i128> {
        match self {
            Scalar::Int(i) => Some((*i).into()),
            Scalar::UInt(u) => Some((*u).into()),
            _ => None,
        }
    }

    fn as_f64(&self) -> Option<f64> {
        match self {
            Scalar::Int(i) => Some(*i as f64),
            Scalar::UInt(u) => Some(*u as f64),
            Scalar::Float(f) => Some(*f),
            _ => None,
        }
    }
}

impl From<Scalar<'_>> for Value {
    fn from(s: Scalar<'_>) -> Self {
        match s {
            Scalar::Null => Value::Null,
            Scalar::Bool(b) => Value::Bool(b),
            Scalar::Int(i) => Value::Int(i),
            Scalar::UInt(u) => Value::UInt(u),
            Scalar::Float(f) => Value::Float(f),
            Scalar::Str(s) => Value::Str(s.into_owned()),
        }
    }
}

fn int_scalar(i: i128) -> Option<Scalar<'static>> {
    if let Ok(v) = i64::try_from(i) {
        Some(Scalar::Int(v))
    } else {
        u64::try_from(i).ok().map(Scalar::UInt)
    }
}

// ---------------------------------------------------------------------------------------------------------------
// Render

/// Writes a value's display form, HTML-escaped when `escape` is true. [`Safe`] is never escaped.
pub trait Render {
    /// Appends the display form to `out`.
    fn render(&self, out: &mut String, escape: bool);
}

/// The unescaped display form of `value` (what filters work on).
pub fn display<R: Render + ?Sized>(value: &R) -> String {
    let mut out = String::new();
    value.render(&mut out, false);
    out
}

fn push_str(out: &mut String, s: &str, escape: bool) {
    if escape {
        escape_into(out, s);
    } else {
        out.push_str(s);
    }
}

macro_rules! render_display {
    ($($t:ty),*) => {$(
        impl Render for $t {
            fn render(&self, out: &mut String, _escape: bool) {
                let _ = write!(out, "{}", self);
            }
        }
    )*};
}
render_display!(
    i8, i16, i32, i64, i128, isize, u8, u16, u32, u64, u128, usize, f32, f64, bool
);

impl Render for char {
    fn render(&self, out: &mut String, escape: bool) {
        push_str(out, self.encode_utf8(&mut [0; 4]), escape);
    }
}
impl Render for str {
    fn render(&self, out: &mut String, escape: bool) {
        push_str(out, self, escape);
    }
}
impl Render for String {
    fn render(&self, out: &mut String, escape: bool) {
        push_str(out, self, escape);
    }
}
impl Render for Safe {
    fn render(&self, out: &mut String, _escape: bool) {
        out.push_str(&self.0);
    }
}
impl Render for Null {
    fn render(&self, _out: &mut String, _escape: bool) {}
}
impl Render for Scalar<'_> {
    fn render(&self, out: &mut String, escape: bool) {
        match self {
            Scalar::Null => {}
            Scalar::Bool(b) => b.render(out, escape),
            Scalar::Int(i) => i.render(out, escape),
            Scalar::UInt(u) => u.render(out, escape),
            Scalar::Float(f) => f.render(out, escape),
            Scalar::Str(s) => push_str(out, s, escape),
        }
    }
}
impl<T: Render> Render for Option<T> {
    fn render(&self, out: &mut String, escape: bool) {
        if let Some(v) = self {
            v.render(out, escape);
        }
    }
}
impl<T: Render + ?Sized> Render for &T {
    fn render(&self, out: &mut String, escape: bool) {
        (**self).render(out, escape);
    }
}
impl<T: Render + ?Sized> Render for &mut T {
    fn render(&self, out: &mut String, escape: bool) {
        (**self).render(out, escape);
    }
}
impl<T: Render + ?Sized> Render for Box<T> {
    fn render(&self, out: &mut String, escape: bool) {
        (**self).render(out, escape);
    }
}
impl<T: Render + ?Sized> Render for Rc<T> {
    fn render(&self, out: &mut String, escape: bool) {
        (**self).render(out, escape);
    }
}
impl<T: Render + ?Sized> Render for Arc<T> {
    fn render(&self, out: &mut String, escape: bool) {
        (**self).render(out, escape);
    }
}
impl<B: Render + ToOwned + ?Sized> Render for Cow<'_, B> {
    fn render(&self, out: &mut String, escape: bool) {
        (**self).render(out, escape);
    }
}

// ---------------------------------------------------------------------------------------------------------------
// Truthy

/// Truthiness: `false`, `0`, `0.0`, `""`, empty lists and maps, and `None` are falsy.
pub trait Truthy {
    /// Whether the value counts as true in `@if`, `!`, `&&` and `||`.
    fn truthy(&self) -> bool;
}

macro_rules! truthy_num {
    ($($t:ty),*) => {$(
        impl Truthy for $t {
            fn truthy(&self) -> bool { *self != (0 as $t) }
        }
    )*};
}
truthy_num!(
    i8, i16, i32, i64, i128, isize, u8, u16, u32, u64, u128, usize, f32, f64
);

impl Truthy for bool {
    fn truthy(&self) -> bool {
        *self
    }
}
impl Truthy for char {
    fn truthy(&self) -> bool {
        true
    }
}
impl Truthy for str {
    fn truthy(&self) -> bool {
        !self.is_empty()
    }
}
impl Truthy for String {
    fn truthy(&self) -> bool {
        !self.is_empty()
    }
}
impl Truthy for Safe {
    fn truthy(&self) -> bool {
        !self.0.is_empty()
    }
}
impl Truthy for Null {
    fn truthy(&self) -> bool {
        false
    }
}
impl Truthy for Scalar<'_> {
    fn truthy(&self) -> bool {
        match self {
            Scalar::Null => false,
            Scalar::Bool(b) => *b,
            Scalar::Int(i) => *i != 0,
            Scalar::UInt(u) => *u != 0,
            Scalar::Float(f) => *f != 0.0,
            Scalar::Str(s) => !s.is_empty(),
        }
    }
}
impl<T> Truthy for [T] {
    fn truthy(&self) -> bool {
        !self.is_empty()
    }
}
impl<T> Truthy for Vec<T> {
    fn truthy(&self) -> bool {
        !self.is_empty()
    }
}
impl<K, V, S> Truthy for HashMap<K, V, S> {
    fn truthy(&self) -> bool {
        !self.is_empty()
    }
}
impl<K, V> Truthy for BTreeMap<K, V> {
    fn truthy(&self) -> bool {
        !self.is_empty()
    }
}
impl<T: Truthy> Truthy for Option<T> {
    fn truthy(&self) -> bool {
        self.as_ref().is_some_and(Truthy::truthy)
    }
}
impl<T: Truthy + ?Sized> Truthy for &T {
    fn truthy(&self) -> bool {
        (**self).truthy()
    }
}
impl<T: Truthy + ?Sized> Truthy for Box<T> {
    fn truthy(&self) -> bool {
        (**self).truthy()
    }
}
impl<T: Truthy + ?Sized> Truthy for Rc<T> {
    fn truthy(&self) -> bool {
        (**self).truthy()
    }
}
impl<T: Truthy + ?Sized> Truthy for Arc<T> {
    fn truthy(&self) -> bool {
        (**self).truthy()
    }
}
impl<B: Truthy + ToOwned + ?Sized> Truthy for Cow<'_, B> {
    fn truthy(&self) -> bool {
        (**self).truthy()
    }
}

/// Truthiness for generated code, also for types without a [`Truthy`] impl.
///
/// Generated code calls `(&&Probe(&value)).mold_truthy()`; method resolution picks the first that applies:
/// [`ViaTruthy`] (the type implements `Truthy`), [`ViaOption`] (an `Option` of any type: `is_some`), [`ViaAny`]
/// (any other value, such as a struct: true). This matches the interpreter, where a struct is a non-empty map.
pub struct Probe<'a, T: ?Sized>(pub &'a T);

impl<T: ?Sized> Clone for Probe<'_, T> {
    fn clone(&self) -> Self {
        *self
    }
}
impl<T: ?Sized> Copy for Probe<'_, T> {}

/// See [`Probe`].
pub trait ViaTruthy {
    /// Truthiness.
    fn mold_truthy(self) -> bool;
}
impl<T: Truthy + ?Sized> ViaTruthy for &&Probe<'_, T> {
    fn mold_truthy(self) -> bool {
        self.0.truthy()
    }
}
/// See [`Probe`].
pub trait ViaOption {
    /// Truthiness.
    fn mold_truthy(self) -> bool;
}
impl<T> ViaOption for &Probe<'_, Option<T>> {
    fn mold_truthy(self) -> bool {
        self.0.is_some()
    }
}
/// See [`Probe`].
pub trait ViaAny {
    /// Truthiness.
    fn mold_truthy(self) -> bool;
}
impl<T: ?Sized> ViaAny for Probe<'_, T> {
    fn mold_truthy(self) -> bool {
        true
    }
}

